const resume = String($input.first().json.resume_text || '').toLowerCase();

const aliases = {
  AWS: ['aws', 'amazon web services', 'ec2', 'lambda'],
  Terraform: ['terraform', 'infrastructure as code', 'iac'],
  Docker: ['docker', 'containerisation', 'containerization'],
  Kubernetes: ['kubernetes', 'k8s', 'eks'],
  Python: ['python', 'boto3'],
  Linux: ['linux', 'ubuntu', 'rhel', 'red hat'],
  Networking: ['networking', 'vpc', 'dns', 'tcp/ip', 'subnet'],
  'CI/CD': ['ci/cd', 'continuous integration', 'github actions', 'jenkins', 'gitlab ci'],
  GitOps: ['gitops', 'argocd', 'argo cd', 'fluxcd', 'flux cd'],
  Security: ['security', 'iam', 'devsecops', 'least privilege'],
  Monitoring: ['monitoring', 'observability', 'prometheus', 'grafana', 'cloudwatch']
};

const escaped = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const includesAlias = alias => new RegExp(`(^|[^a-z0-9])${escaped(alias)}([^a-z0-9]|$)`).test(resume);
const skills = Object.entries(aliases)
  .filter(([, values]) => values.some(includesAlias))
  .map(([skill]) => skill);

return [{ json: { ...$input.first().json, detected_skills: skills } }];

const skills = $input.first().json.detected_skills;

let recommendations = [];

if (!skills.includes("Python")) {
  recommendations.push("Learn Python automation and scripting.");
}

if (!skills.includes("Jenkins")) {
  recommendations.push("Gain experience with Jenkins CI/CD.");
}

if (!skills.includes("AWS Solutions Architecture")) {
  recommendations.push("Develop AWS Solutions Architect skills.");
}

if (!skills.includes("Ansible")) {
  recommendations.push("Learn configuration management with Ansible.");
}

return [
  {
    json: {
      detected_skills: skills,
      recommendations: recommendations
    }
  }
];

const input = $input.first().json;
const skills = input.detected_skills || [];
const requiredSkills = [
  'AWS', 'Terraform', 'Docker', 'Kubernetes', 'Python',
  'Linux', 'Networking', 'CI/CD', 'Security', 'Monitoring'
];
const matchedSkills = requiredSkills.filter(skill => skills.includes(skill));
const missingSkills = requiredSkills.filter(skill => !skills.includes(skill));

return [{
  json: {
    ...input,
    matched_skills: matchedSkills,
    missing_skills: missingSkills,
    readiness_score: Math.round((matchedSkills.length / requiredSkills.length) * 100),
    scoring_version: '2.0'
  }
}];
